-- Status bar content seeded from the authoritative database (quotes and grammar
-- facts only; retired usage tips are not restored). last_shown_at is runtime state
-- and deliberately starts empty. Idempotent via the primary key.
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (3, '"The limits of my language mean the limits of my world." — Ludwig Wittgenstein', 'quote', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (4, 'Grammar Fact: "I am" is the shortest complete sentence in the English language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (11, 'Grammar Fact: "The quick brown fox jumps over the lazy dog" is a pangram, using every letter in the alphabet.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (12, 'Grammar Fact: "Queueing" is the only word in English with five consecutive vowels.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (13, 'Grammar Fact: The most commonly used word in English is "the".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (14, 'Grammar Fact: "Set" has more definitions than any other word in the English language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (15, 'Grammar Fact: The word "alphabet" comes from the first two letters of the Greek alphabet: alpha and beta.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (16, 'Grammar Fact: "Underground" is the only word in the English language that begins and ends with the letters "und."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (17, 'Grammar Fact: (Article Usage) The word "the" is a definite article; "a" and "an" are indefinite articles.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (18, 'Grammar Fact: (Punctuation) The Oxford Comma is the final comma in a list of three or more items.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (19, 'Grammar Fact: (Spelling) "I before E except after C" is a common rule, but it has many exceptions like "weird".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (20, '"To have another language is to possess a second soul."', 'quote', 'Charlemagne', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (21, '"Language is the blood of the soul into which thoughts run and out of which they grow."', 'quote', 'Oliver Wendell Holmes', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (22, '"One language sets you in a corridor for life. Two languages open every door along the way."', 'quote', 'Frank Smith', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (23, '"Knowledge of languages is the doorway to wisdom."', 'quote', 'Roger Bacon', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (24, '"Change your language and you change your thoughts."', 'quote', 'Karl Albrecht', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (25, '"Learning is a treasure that will follow its owner everywhere."', 'quote', 'Chinese Proverb', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (61, 'Grammar Fact: The word "uncopyrightable" is the longest English word that can be written without repeating a letter.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (62, 'Grammar Fact: "Screeched" is the longest one-syllable word in the English language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (63, 'Grammar Fact: The "dot" over the letter "i" or "j" is called a tittle.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (64, 'Grammar Fact: "Dreamt" is the only English word that ends in the letters "mt".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (65, 'Grammar Fact: English is the official language of 67 different countries.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (66, 'Grammar Fact: A new word is added to the dictionary approximately every two hours.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (67, 'Grammar Fact: The shortest, oldest, and most commonly used word is "I".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (68, 'Grammar Fact: "Almost" is the longest word in English with all the letters in alphabetical order.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (69, 'Grammar Fact: "Rhythm" is the longest English word without a real vowel (a, e, i, o, u).', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (70, 'Grammar Fact: A "pangram" sentence is one that contains every letter in the language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (71, 'Grammar Fact: "E" is the most common letter in the English language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (72, 'Grammar Fact: The word "swims" will be "swims" even when turned upside down.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (73, 'Grammar Fact: The symbol "@" is officially called an "asperand" or an "ampersat".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (74, 'Grammar Fact: (Subject-Verb) Collective nouns like "team" can be singular or plural depending on the dialect.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (75, 'Grammar Fact: (Prepositions) Ending a sentence with a preposition is actually acceptable in modern English.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (76, 'Grammar Fact: (Adjectives) There is a standard order for adjectives: opinion, size, age, shape, color, origin, material, purpose.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (77, 'Grammar Fact: (Pronouns) "They" has been used as a singular pronoun since at least the 14th century.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (78, 'Grammar Fact: (Verbs) The verb "to be" is the most irregular verb in the English language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (79, 'Grammar Fact: (Punctuation) The "interrobang" is a non-standard punctuation mark that combines a question mark and an exclamation point.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (80, 'Grammar Fact: The longest word in any of the major English dictionaries is "pneumonoultramicroscopicsilicovolcanoconiosis".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (81, 'Grammar Fact: The word "mortgage" comes from a French word meaning "death pledge".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (82, 'Grammar Fact: The words "skunk", "papoose", and "squash" are all Native American in origin.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (83, 'Grammar Fact: Shakespeare added over 1,700 words to the English language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (84, 'Grammar Fact: "Goodbye" originally comes from the Old English phrase "God be with ye".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (85, 'Grammar Fact: The average person knows about 20,000 to 35,000 words.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (86, 'Grammar Fact: More people have learned English as a second language than there are native speakers.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (87, 'Grammar Fact: The word "set" has the most meanings of any word in English.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (88, 'Grammar Fact: "Typewriter" is the longest word you can make using only the top row of a QWERTY keyboard.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (89, 'Grammar Fact: The word "checkmate" in chess comes from the Persian phrase "Shah Mat," meaning "the king is helpless."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (90, 'Grammar Fact: "Town" is the oldest word in the English language that is still used today.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (91, 'Grammar Fact: The most used adjective in English is "good".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (92, 'Grammar Fact: The word "news" was once considered plural, and you could say "the news are bad."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (93, 'Grammar Fact: "Oxymoron" is itself an oxymoron; in Greek, "oxys" means sharp and "moros" means stupid.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (94, 'Grammar Fact: The word "robot" comes from the Czech word for "forced labor."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (95, 'Grammar Fact: English used to have grammatical gender (like German or French) until the 1200s.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (96, 'Grammar Fact: The pilcrow (¶) is the symbol used to denote a new paragraph.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (97, 'Grammar Fact: (Verb Tense) The present perfect tense connects the past to the present.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (98, 'Grammar Fact: (Word Form) Adverbs often end in "-ly", but not all of them do (e.g., "fast", "well").', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (99, 'Grammar Fact: (Comparison) "Unique" technically shouldn''t be compared (no "more unique").', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (100, 'Grammar Fact: (Negation) Avoid double negatives in formal writing as they can cancel each other out.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (101, '"The limits of my language mean the limits of my world."', 'quote', 'Ludwig Wittgenstein', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (102, '"To have another language is to possess a second soul."', 'quote', 'Charlemagne', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (103, '"A different language is a different vision of life."', 'quote', 'Federico Fellini', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (104, '"Language is the road map of a culture. It tells you where its people come from and where they are going."', 'quote', 'Rita Mae Brown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (105, '"If you talk to a man in a language he understands, that goes to his head. If you talk to him in his language, that goes to his heart."', 'quote', 'Nelson Mandela', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (106, '"One language sets you in a corridor for life. Two languages open every door along the way."', 'quote', 'Frank Smith', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (107, '"Learning is a treasure that will follow its owner everywhere."', 'quote', 'Chinese Proverb', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (108, '"Language is wine upon the lips."', 'quote', 'Virginia Woolf', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (109, '"You can never understand one language until you understand at least two."', 'quote', 'Geoffrey Willans', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (110, '"Knowledge of languages is the doorway to wisdom."', 'quote', 'Roger Bacon', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (111, '"Language exerts hidden power, like a moon on the tides."', 'quote', 'Rita Mae Brown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (112, '"A man who knows two languages is worth two men."', 'quote', 'French Proverb', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (113, '"The more languages you know, the more you are human."', 'quote', 'Tomáš Garrigue Masaryk', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (114, '"Language is the light of the mind."', 'quote', 'John Stuart Mill', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (115, '"To learn a language is to have one more window from which to look at the world."', 'quote', 'Chinese Proverb', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (116, '"Words are a pretext. It is the inner bond that draws one person to another, not words."', 'quote', 'Rumi', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (117, '"Change your language and you change your thoughts."', 'quote', 'Karl Albrecht', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (118, '"Language is the soul of intellect, and writing is the embodyment of language."', 'quote', 'Samuel Johnson', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (119, '"The soul of a people is found in its language."', 'quote', 'Johann Gottfried von Herder', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (120, '"Without language, one cannot talk to people and understand them; one cannot share their hopes and aspirations."', 'quote', 'Nelson Mandela', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (121, '"Language is the apparel in which your thoughts parade before the public."', 'quote', 'George Crane', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (122, '"The beauty of a language is in the words; the spirit is in the grammar."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (123, '"A language is not just a body of vocabulary or a set of grammatical rules. A language is a flash of the human spirit."', 'quote', 'Wade Davis', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (124, '"Grammar is the logic of speech, even as logic is the grammar of reason."', 'quote', 'Richard Chenevix Trench', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (125, '"Language is the mirror of the mind."', 'quote', 'Noam Chomsky', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (126, '"A language is a system of responses of a people to its environment."', 'quote', 'Jose Rizal', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (127, '"Words are the small change of thought."', 'quote', 'Jules Renard', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (128, '"Language is the key to the heart of the people."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (129, '"Every language is a world. Without it, the world is incomplete."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (130, '"Words are, of course, the most powerful drug used by mankind."', 'quote', 'Rudyard Kipling', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (165, 'Grammar Fact: The word "shampoo" comes from a Hindi word meaning "to massage".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (166, 'Grammar Fact: "Go" is the shortest complete sentence in the English language.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (167, 'Grammar Fact: "Subbookkeeper" is the only word with four consecutive double letters.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (168, 'Grammar Fact: The word "nerd" was first coined by Dr. Seuss in 1950.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (169, 'Grammar Fact: "Ewe" and "you" are pronounced exactly the same but have no letters in common.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (170, 'Grammar Fact: The word "clue" originally meant a ball of thread.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (171, 'Grammar Fact: (Nouns) "Data" was originally the plural of "datum," but is now often used as a singular mass noun.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (172, 'Grammar Fact: (Prepositions) "Into" implies movement toward the inside; "in" implies position.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (173, 'Grammar Fact: (Subject-Verb) "The number of..." takes a singular verb; "A number of..." takes a plural verb.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (174, 'Grammar Fact: (Articles) Names of most countries do not take an article, but "The United States" and "The Netherlands" do.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (175, 'Grammar Fact: The dot on top of "i" and "j" is officially called a "tittle".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (176, 'Grammar Fact: "Facetious" contains all the vowels in alphabetical order.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (177, 'Grammar Fact: The word "trivia" comes from the Latin for "three roads".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (178, 'Grammar Fact: (Spelling) "Accommodate" has two "c"s and two "m"s.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (179, 'Grammar Fact: (Punctuation) The "slash" (/) is also known as a virgule.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (180, 'Grammar Fact: The word "lucid" comes from the Latin word for "light".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (181, 'Grammar Fact: "Dreamt" is the only English word ending in "mt".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (182, 'Grammar Fact: (Verbs) "Will" and "shall" used to have different rules for different persons, but they are now mostly interchangeable.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (183, 'Grammar Fact: (Nouns) "Physics" and "Mathematics" are singular despite ending in "s".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (184, 'Grammar Fact: English has the largest vocabulary of any language in the world.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (185, 'Grammar Fact: About 4,000 words are added to the dictionary every year.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (186, 'Grammar Fact: "Stewardesses" is the longest word that can be typed with only the left hand.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (187, 'Grammar Fact: "Lol" was added to the Oxford English Dictionary in 2011.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (188, 'Grammar Fact: (Adjectives) "Oldest" is used for age; "eldest" is specifically for family members.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (189, 'Grammar Fact: (Pronouns) "Mine" and "Yours" are possessive pronouns; they do not use apostrophes.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (190, 'Grammar Fact: "Listen" is an anagram of "silent".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (191, 'Grammar Fact: The word "alphabet" is derived from the first two Greek letters.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (192, 'Grammar Fact: (Word Order) Adverbs of frequency (like "always") usually go before the main verb.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (193, 'Grammar Fact: (Tense) The past perfect tense ("had done") describes an action completed before another past action.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (194, 'Grammar Fact: (Conjunctions) "Unless" means "if not".', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (195, 'Grammar Fact: The word "synonym" does not have a synonym (mostly).', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (196, 'Grammar Fact: (Clarity) Avoid "empty" subjects like "It is..." to make your writing more direct.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (197, 'Grammar Fact: "Rhythms" is the longest word without a vowel (excluding "y").', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (198, '"Mistakes are the portals of discovery."', 'quote', 'James Joyce', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (199, '"Language is a process of free creation; its laws and principles are fixed, but the manner in which the principles of generation are used is free and infinitely varied."', 'quote', 'Noam Chomsky', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (200, '"The word ''listen'' contains the same letters as the word ''silent''."', 'quote', 'Alfred Brendel', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (201, '"A language is a system of arbitrary vocal symbols by means of which a social group cooperates."', 'quote', 'Bernard Bloch', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (202, '"The structure of a language determines the way in which speakers of that language perceive the world."', 'quote', 'Benjamin Lee Whorf', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (203, '"Slang is a language that rolls up its sleeves, spits on its hands and goes to work."', 'quote', 'Carl Sandburg', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (204, '"Language is a city to the building of which every human being brought a stone."', 'quote', 'Ralph Waldo Emerson', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (205, '"Words are but symbols for the relations of things to one another and to us; nowhere do they touch upon absolute truth."', 'quote', 'Friedrich Nietzsche', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (206, '"Proper words in proper places, make the true definition of a style."', 'quote', 'Jonathan Swift', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (207, '"All language is but a poor translation."', 'quote', 'Franz Kafka', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (208, '"The difference between the right word and the almost right word is the difference between lightning and a lightning bug."', 'quote', 'Mark Twain', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (209, '"Language is the mother of thought, not its handmaid."', 'quote', 'Karl Kraus', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (210, '"Words are the voice of the heart."', 'quote', 'Confucius', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (211, '"Kind words can be short and easy to speak, but their echoes are truly endless."', 'quote', 'Mother Teresa', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (212, '"The Pen is mightier than the Sword."', 'quote', 'Edward Bulwer-Lytton', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (213, '"Good words are worth much, and cost little."', 'quote', 'George Herbert', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (214, '"The word is half his that speaks, and half his that hears it."', 'quote', 'Michel de Montaigne', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (215, '"A word is not a crystal, transparent and unchanged; it is the skin of a living thought."', 'quote', 'Oliver Wendell Holmes Jr.', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (216, '"Language is the invention of people who want to catch and hold the world."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (217, '"Without words, without writing and without books there would be no history, there could be no concept of humanity."', 'quote', 'Hermann Hesse', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (218, '"Language is a tool of the mind."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (219, '"A nation is a group of people who share the same language and the same history."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (220, '"The first step toward wisdom is calling things by their right names."', 'quote', 'Chinese Proverb', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (221, '"Language is the dress of thought."', 'quote', 'Samuel Johnson', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (222, '"Words are the pegs to hang ideas on."', 'quote', 'Henry Ward Beecher', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (223, '"One forgetful word can seal a fate."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (224, '"The turn of a sentence can change a mood."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (225, '"Words have the power to both destroy and heal."', 'quote', 'Buddha', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (226, '"In the beginning was the Word."', 'quote', 'Bible', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (227, '"Language is the house of being."', 'quote', 'Martin Heidegger', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (228, '"The limits of my language are the limits of my mind."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (229, '"Talk is cheap, but words are precious."', 'quote', 'Unknown', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (230, '"Silence is the language of God, all else is poor translation."', 'quote', 'Rumi', NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (231, 'Grammar Fact: Use a singular verb after "each" when it is the subject: "Each answer is useful."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (232, 'Grammar Fact: In standard English, "fewer" goes with countable nouns; "less" usually goes with amounts.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (233, 'Grammar Fact: Use "who" for a person doing the action and "whom" for a person receiving it in formal English.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (234, 'Grammar Fact: A modal verb such as "can" or "should" is followed by the base verb: "can go," not "can goes."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (235, 'Grammar Fact: After "did," use the base verb: "Did you see it?"', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (236, 'Grammar Fact: In indirect questions, use statement word order: "Do you know where she is?"', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (237, 'Grammar Fact: Use "although" or "but" to connect contrasting ideas, usually not both for the same contrast.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (238, 'Grammar Fact: A semicolon can join two closely related independent clauses.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (239, 'Grammar Fact: A colon can introduce an explanation, example, or list after a complete clause.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (240, 'Grammar Fact: In a defining relative clause, "that" is common for things: "the book that I borrowed."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (241, 'Grammar Fact: Use "whose" to show possession: "the student whose idea helped."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (242, 'Grammar Fact: "Advice" is uncountable in standard English; say "some advice" or "a piece of advice."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (243, 'Grammar Fact: "Information" is uncountable in standard English; use "a piece of information" for one item.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (244, 'Grammar Fact: "News" ends in s but usually takes a singular verb: "The news is good."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (245, 'Grammar Fact: Use "a" before a consonant sound and "an" before a vowel sound: "a university," "an hour."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (246, 'Grammar Fact: Use "the" when the reader can identify which particular thing you mean.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (247, 'Grammar Fact: "Since" often marks a starting point; "for" often marks a duration: "since May," "for a week."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (248, 'Grammar Fact: "During" takes a noun phrase; "while" usually introduces a clause: "during lunch," "while we ate."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (249, 'Grammar Fact: "Between" commonly relates two items; "among" commonly relates members of a group.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (250, 'Grammar Fact: "Beside" means next to; "besides" means in addition to.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (251, 'Grammar Fact: Use "used to" for past habits that no longer happen: "We used to walk here."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (252, 'Grammar Fact: "Be used to" means be accustomed to, and "to" is followed by a noun or gerund.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (253, 'Grammar Fact: Use "I have lived here for five years" when the period continues to now.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (254, 'Grammar Fact: In standard English, "If I were you" uses "were" for an imaginary situation.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (255, 'Grammar Fact: In a second conditional, "would" belongs in the result clause: "If I had time, I would help."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (256, 'Grammar Fact: Put "already" and "yet" near the verb; "yet" often appears in questions and negatives.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (257, 'Grammar Fact: "Still" often signals that a situation continues: "She is still working."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (258, 'Grammar Fact: "Too" can mean more than wanted; "enough" can mean as much as needed.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (259, 'Grammar Fact: Use "so" before an adjective and "such" before a noun phrase: "so kind," "such a kind person."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (260, 'Grammar Fact: "Everyday" is an adjective; "every day" means each day.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (261, 'Grammar Fact: "Maybe" is an adverb; "may be" is a verb phrase: "Maybe it may be ready."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (262, 'Grammar Fact: "Its" shows possession; "it’s" means "it is" or "it has."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (263, 'Grammar Fact: A participle phrase should clearly describe the noun that follows it.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (264, 'Grammar Fact: In "She enjoys reading," the verb "enjoy" is followed by a gerund.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (265, 'Grammar Fact: In "They decided to leave," the verb "decide" is followed by a to-infinitive.', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (266, 'Grammar Fact: "Make" is followed by an object and the base verb: "That made me laugh."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (267, 'Grammar Fact: "Suggest" can be followed by a gerund: "She suggested taking a break."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (268, 'Grammar Fact: "Prefer" can use "to" to compare choices: "I prefer tea to coffee."', 'grammar_fact', NULL, NULL);
INSERT OR IGNORE INTO status_messages (id, content, type, author, source) VALUES (269, 'Grammar Fact: In reported speech, pronouns and time words may change to match the new viewpoint.', 'grammar_fact', NULL, NULL);
